Q: How to get primary key of table? A: <pre class="lang-php prettyprint-override"><code>&lt;?php

function mysql_get_prim_key($table){
    $sql = &quot;SHOW INDEX FROM $table WHERE Key_name = 'PRIMARY'&quot;;
    $gp = mysql_query($sql);
    $cgp = mysql_num_rows($gp);

    if ($cgp &gt; 0) {
        // Note I'm not using a while loop because I never use more than one prim key column
        $agp = mysql_fetch_array($gp);
        extract($agp);

        return($Column_name);
    } else {
        return(false);
    }
}

?&gt;
</code></pre>
